import { ref } from 'vue';
export default {
  name: 'LoginForm',
  props: {
    loading: Boolean
  },
  emits: ['submit'],
  setup(props, {
    emit
  }) {
    const username = ref('');
    const password = ref('');
    const submitForm = () => {
      emit('submit', {
        username: username.value,
        password: password.value
      });
    };
    return {
      username,
      password,
      submitForm
    };
  }
};
